{
  "findings": [
    {
      "ref": "[D540]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox uses age-based defaults with Roblox Kids and Roblox Select to restrict content for younger users.",
      "stance": "mitigation",
      "quote": "Roblox Kids and Roblox Select use age-based defaults to determine what games are available to younger users."
    },
    {
      "ref": "[D540]",
      "area": "content",
      "claim": "A parent reports that games with social hangouts or free-form user creation are only available to age-checked users 16 and older.",
      "stance": "risk",
      "quote": "Games with social hangouts or free-form user creation are only available to age-checked users 16 and older."
    },
    {
      "ref": "[D540]",
      "area": "content",
      "claim": "A parent reports that Minimal content may contain occasional mild violence, light unrealistic blood, and/or occasional mild fear.",
      "stance": "neutral",
      "quote": "MinimalMay contain occasional mild violence, light unrealistic blood, and/or occasional mild fear."
    },
    {
      "ref": "[D540]",
      "area": "content",
      "claim": "A parent reports that Moderate content may contain moderate violence, light realistic blood, moderate crude humor, unplayable gambling content, social hangouts without private spaces, free-form user creation such as in-game drawing tools, and/or moderate fear.",
      "stance": "neutral",
      "quote": "ModerateMay contain moderate violence, light realistic blood, moderate crude humor, unplayable gambling content, social hangouts without private spaces, free-form user creation such as in-game drawing tools, and/or moderate fear."
    },
    {
      "ref": "[D540]",
      "area": "content",
      "claim": "A parent reports that Content May Vary may contain Minimal, Mild, or Moderate content and is rated for players 16 and older without a full questionnaire.",
      "stance": "neutral",
      "quote": "Content May VaryMay contain Minimal, Mild, or Moderate content. The creator hasn't completed the full Maturity & Compliance questionnaire, so this game doesn't have a more precise rating."
    },
    {
      "ref": "[D540]",
      "area": "content",
      "claim": "A parent reports that 16+ Content may contain themes centered on sensitive social, political, or religious issues and can also contain social hangouts without private spaces, free-form user creation, and other content listed under Moderate.",
      "stance": "risk",
      "quote": "16+ ContentMay contain themes centered on sensitive social, political, or religious issues. Can also contain social hangouts without private spaces, free-form user creation, and other content listed under Moderate."
    },
    {
      "ref": "[D540]",
      "area": "content",
      "claim": "A parent reports that Restricted and 18+ Content may contain strong violence, heavy realistic blood, moderate crude humor, romantic themes, unplayable gambling content, the presence of alcohol, strong language, social hangouts with private spaces, extended AI interactions, and/or moderate fear.",
      "stance": "risk",
      "quote": "Restricted and 18+ ContentMay contain strong violence, heavy realistic blood, moderate crude humor, romantic themes, unplayable gambling content, the presence of alcohol, strong language, social hangouts with private spaces, extended AI interactions, and/or moderate fear."
    },
    {
      "ref": "[D540]",
      "area": "contact",
      "claim": "A parent reports that users must still comply with Roblox’s Restricted Content Policy and Community Standards, and language that harasses, discriminates, incites violence, or threatens others, or is used in a sexual context is not allowed.",
      "stance": "mitigation",
      "quote": "Strong language policies will apply to both in-experience content and how users communicate within text and voice chat. Users must still comply with Roblox’s [Restricted Content Policy](https://en.help.roblox.com/hc/en-us/articles/15869919570708) and [Community Standards](https://en.help.roblox.com/hc/en-us/articles/203313410). Roblox won’t allow language that is used to harass, discriminate, incite violence, or threaten others, or used in a sexual context."
    },
    {
      "ref": "[D540]",
      "area": "data",
      "claim": "A parent reports that Roblox’s Privacy and Cookie Policy explains how cookies are used to personalize and enhance the experience, and users can manage preferences in the Cookie Consent Tool.",
      "stance": "neutral",
      "quote": "We use cookies to personalize and enhance your experience on our site. Visit our [Privacy Policy](https://en.help.roblox.com/hc/en-us/articles/115004630823-Roblox-Privacy-and-Cookie-Policy) for more information on our data collection practices. By clicking Accept, you agree to our use of cookies for the purposes listed in our [Cookie Consent Tool](https://en.help.roblox.com/hc/en-us/articles/8862768451604-Content-Maturity-Ratings#). To see a complete list of the companies that use these cookies and other technologies and to tell us whether they can be used on your device or not, access our Cookie Consent Tool."
    }
  ]
}
